import React, { useState } from 'react';
import { Stat, PageTitle, Field, Modal, Status, Empty } from '../../components/common';
import './BookingsPage.css';

export default function BookingsPage({leads}) { const won=leads.filter(l=>l.status==='Won'); return <div className="module-page module-page--bookings"><PageTitle eyebrow="DEAL DESK" title="Bookings" subtitle="Review closed deals and keep upcoming bookings visible."/><div className="stats-grid"><Stat label="Closed won" value={won.length} change="Marked as Won" icon="✓" tone="green" foot="Based on lead status"/><Stat label="Pipeline value" value={money(leads.filter(l=>!['Won','Lost'].includes(l.status)).reduce((s,l)=>s+Number(l.budget||0),0))} change="Open opportunity budget" icon="₹" tone="purple" foot="Not a revenue forecast"/><Stat label="Booking documents" value="0" change="Not integrated" icon="▤" tone="blue" foot="Document workflow to build"/><Stat label="Pending payments" value="—" change="Connect payment records" icon="◷" tone="orange" foot="No real transactions in demo"/></div><div className="panel"><div className="panel-head"><div><h3>Won deals</h3><p>Leads moved to Won stage</p></div></div>{won.length?<div className="table-wrap"><table><thead><tr><th>CUSTOMER</th><th>LOCATION</th><th>ASSIGNED</th><th>BUDGET</th></tr></thead><tbody>{won.map(l=><tr key={l.id}><td>{l.name}</td><td>{l.location}</td><td>{l.assigned}</td><td>{money(l.budget)}</td></tr>)}</tbody></table></div>:<Empty title="No confirmed bookings yet" desc="When a lead is moved to Won, it will appear here. Booking documents and payments require a dedicated workflow."/>}</div></div>; }
